create database company;
use company;

create table employee (
    id int,
    name varchar(20)
);

insert into employee values (1, 'ram');

select * from employee;

-- Verify installation by running a simple query
SELECT VERSION();
SHOW DATABASES;

-- DDL example
create table product (id int, name varchar(20));

-- DML example
insert into product values (1, 'pen');

-- DQL example
select * from product;

-- CREATE
create table product (
    id int,
    name varchar(20)
);

-- ALTER
alter table product add price int;

-- DROP
drop table product;

-- INSERT
insert into product values (1, 'pen');

-- UPDATE
update product
set name = 'pencil'
where id = 1;

-- DELETE
delete from product where id = 1;

-- DCL
grant select on product to user1;
revoke select on product from user1;

-- TCL
commit;
rollback;

create table student (
    id int primary key,
    name varchar(20)
);

create table student_course (
    course_id int,
    id int,
    foreign key (id) references student(id)
);

-- Subquery in WHERE clause
select id from student
where id in (select id from student_course);

-- Subquery returning a single value
select * from student
where id = (select max(id) from student);

-- Create index
create index idx_name on student(name);
create index idx_id on student(id);

-- Show indexes
show index from student;

-- Drop index
drop index idx_name on student;

